下面定义了一个表示二维坐标点的类 `Point`, 并提供了一个带参数的构造函数,但第②行 `Point b;` 会调用编译器自动生成的默认构造函数,将 `b.x` 和 `b.y` 被初始化为 `0.0`,程序可以正常编译运行。
```cpp
class Point {
public:
double x, y;
Point(double px, double py) : x(px), y(py) {}
void print() {
cout << "(" << x << ", " << y << ")";
}
};

int main() {
Point a(3.0, 4.0); // ①
Point b; // ②
a.print();
}
```

下列代码中, `s1->draw();` 和 `s2->draw();`输出不同结果的主要原因是()。
```cpp
class Shape {
public:
virtual void draw() {
cout << "绘制图形" << endl;
}
virtual ~Shape() {}
};

class Circle: public Shape {
public:
void draw() override {
cout << "绘制圆形" << endl;
}
};

class Rectangle: public Shape {
public:
void draw() override {
cout << "绘制矩形" << endl;
}
};

int main() {
Shape* s1 = new Circle();
Shape* s2 = new Rectangle();

s1->draw();
s2->draw();

delete s1;
delete s2;
return 0;
}
```

